+        /// </summary>
+        /// <param name="groupedEmployees"></param>
+        /// <param name="employee"></param>
+        private static void AddEmployeeToGroup(Dictionary<string, List<SocialSecurityEmployeeDto>> groupedEmployees, SocialSecurityEmployeeDto employee)
+        {
+            if (employee.IsInternship)
+            {
+                groupedEmployees[INTERNSHIP_GROUP_KEY].Add(employee);
+                return;
+            }
+
+            var laborRelation = employee.ServiceRelations;
+
+            if (!string.IsNullOrEmpty(laborRelation))
+            {
+                if (!groupedEmployees.ContainsKey(laborRelation))
+                {
+                    groupedEmployees[laborRelation] = new List<SocialSecurityEmployeeDto>();
+                }
+                groupedEmployees[laborRelation].Add(employee);
+            }
+            else
+            {
+                // 没有劳务关系信息的放入"其他"分组
+                if (!groupedEmployees.ContainsKey(OTHER_GROUP_KEY))
+                {
+                    groupedEmployees[OTHER_GROUP_KEY] = new List<SocialSecurityEmployeeDto>();
+                }
+                groupedEmployees[OTHER_GROUP_KEY].Add(employee);
+            }
+        }
+
+        /// <summary>
+        /// 根据缴纳状态对已分组的员工进行最终筛选
+        /// </summary>
+        /// <param name="groupedEmployees"></param>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        private static Dictionary<string, List<SocialSecurityEmployeeDto>> FilterGroupsByPaymentStatus(Dictionary<string, List<SocialSecurityEmployeeDto>> groupedEmployees, SocialSecurityRemind req)
+        {
+            // 0表示查询全部，不需要筛选
+            if (req.PaymentStatus == PaymentStatusEnums.全部)
+            {
+                return groupedEmployees;
+            }
+
+            var filteredGroupedEmployees = new Dictionary<string, List<SocialSecurityEmployeeDto>>();
+
+            foreach (var group in groupedEmployees)
+            {
+                var filteredEmployees = new List<SocialSecurityEmployeeDto>();
+                filteredEmployees.AddRange(group.Value.Where(employee => ShouldIncludeByPaymentStatus(employee, req)));
+
+
+                if (filteredEmployees.Count > 0)
+                {
+                    filteredGroupedEmployees[group.Key] = filteredEmployees;
+                }
+            }
+
+            return filteredGroupedEmployees;
+        }
