+        /// <summary>
+        /// 获取筛选后的钉钉用户列表（用于缴纳）
+        /// </summary>
+        /// <param name="req"></param>
+        /// <param name="monthStart"></param>
+        /// <param name="monthEnd"></param>
+        /// <param name="startTimeMillis"></param>
+        /// <param name="endTimeMillis"></param>
+        /// <returns></returns>
+        private async Task<List<DingTalkUserDetail>> GetFilteredDingTalkUsersForPayment(SocialSecurityRemind req, DateTime monthStart, DateTime monthEnd, long startTimeMillis, long endTimeMillis)
+        {
+            // 查询社保公积金起始缴纳日期在当月的信息
+            var shouldPayUsers = await UnitWork.Find<UserSocialsecurity>(ss =>
+                (req.Type == SocialsecurityTypeEnums.Socialsecurity && ss.SBeginPaymentTime.HasValue && ss.SBeginPaymentTime.Value >= monthStart && ss.SBeginPaymentTime.Value <= monthEnd) ||
+                (req.Type == SocialsecurityTypeEnums.Accumulationfunds && ss.PBeginPaymentTime.HasValue && ss.PBeginPaymentTime.Value >= monthStart && ss.PBeginPaymentTime.Value <= monthEnd)).ToListAsync();
+
+            var shouldPayUserIds = shouldPayUsers.Select(x => x.UserId).ToList();
+            var ddBindUsersPay = await UnitWork.Find<DDBindUser>(x => shouldPayUserIds.Contains(x.UserId)).ToListAsync();
+            var shouldPayDdUserIds = ddBindUsersPay.Select(x => x.DDUserId).ToList();
+
+            // 先获取所有在职员工
+            var allEmployedUsers = await UnitWork.Find<DingTalkUserDetail>(null).ToListAsync();
+            
+            // 再获取所有UserDetail信息，用于筛选实习生
+            var internshipSystemUserIds = await UnitWork.Find<UserDetail>(x => x.LaborRelation == LaborRelationsEnums.Internship).Select(x => x.UserId).ToListAsync();
+
+            // 创建钉钉用户ID到系统用户ID的映射
+            var allDdBindUsers = await UnitWork.Find<DDBindUser>(null).ToListAsync();
+            var allDDUserIdToSystemUserIdMap = allDdBindUsers
+                .GroupBy(x => x.DDUserId)
+                .ToDictionary(g => g.Key, g => g.First().UserId);
+
+            var internshipDDUserIds = allDDUserIdToSystemUserIdMap
+                .Where(kv => internshipSystemUserIds.Contains(kv.Value))
+                .Select(kv => kv.Key)
+                .ToList();
+            
+            // 组合查询条件：当月入职的员工 或 社保/公积金起始缴纳日期在当月的员工 或 实习生
+            var dingTalkUsers = allEmployedUsers.Where(x =>
+                (x.HiredDate >= startTimeMillis && x.HiredDate <= endTimeMillis) ||
+                shouldPayDdUserIds.Contains(x.UserId) ||
+                internshipDDUserIds.Contains(x.UserId));
+            
+            // 添加合并查询字段筛选：同时支持部门和姓名的模糊查询
+            if (!string.IsNullOrEmpty(req.DepartOrName))
+            {
+                dingTalkUsers = dingTalkUsers.Where(x => 
+                    (x.DepartmentCode != null && x.DepartmentCode.Contains(req.DepartOrName)) || 
+                    (x.Name != null && x.Name.Contains(req.DepartOrName)));
+            }
+
+            // 添加劳务关系筛选条件
+            if (!string.IsNullOrEmpty(req.ServiceRelations)&& req.ServiceRelations != "All")
+            {
+                // 来源1：从User表匹配劳务关系
+                var usersWithRelation = await UnitWork.Find<User>(x =>
+                    !string.IsNullOrEmpty(x.ServiceRelations) &&
+                    x.ServiceRelations.Contains(req.ServiceRelations)
+                ).ToListAsync();
+                var systemUserIdsWithRelation = usersWithRelation.Select(x => x.Id).ToList();
+                var ddBindUsersWithRelation = await UnitWork.Find<DDBindUser>(x =>
+                    systemUserIdsWithRelation.Contains(x.UserId)
+                ).ToListAsync();
+                var ddUserIdsFromUser = ddBindUsersWithRelation.Select(x => x.DDUserId).ToList();
+
+                // 来源2：从UserRegisterApply表匹配劳务关系（覆盖未注册完成的人员）
+                var ddUserIdsFromRegister = await UnitWork.Find<UserRegisterApply>(x =>
+                    !string.IsNullOrEmpty(x.ServiceRelations) &&
+                    x.ServiceRelations.Contains(req.ServiceRelations)
+                ).Select(x => x.DDUserId).ToListAsync();
+
+                // 合并两个来源
+                var ddUserIdsWithRelation = ddUserIdsFromUser.Union(ddUserIdsFromRegister).ToList();
+
+                // 筛选出同时满足条件的钉钉用户
+                dingTalkUsers = dingTalkUsers.Where(x => ddUserIdsWithRelation.Contains(x.UserId));
+            }
+
+            return dingTalkUsers.ToList();
+        }
