+        /// <summary>
+        /// 根据退缴状态筛选分组员工
+        /// </summary>
+        /// <param name="groupedEmployees"></param>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        private static Dictionary<string, List<SocialSecurityRefundEmployeeDto>> FilterRefundGroupsByPaymentStatus(Dictionary<string, List<SocialSecurityRefundEmployeeDto>> groupedEmployees, SocialSecurityRemind req)
+        {
+            // 0表示查询全部，不需要筛选
+            if (req.PaymentStatus == PaymentStatusEnums.全部)
+            {
+                return groupedEmployees;
+            }
+
+            var filteredGroupedEmployees = new Dictionary<string, List<SocialSecurityRefundEmployeeDto>>();
+
+            foreach (var group in groupedEmployees)
+            {
+                var filteredEmployees = new List<SocialSecurityRefundEmployeeDto>();
+                filteredEmployees.AddRange(group.Value.Where(employee => ShouldIncludeByRefundPaymentStatus(employee, req)));
+
+                if (filteredEmployees.Count > 0)
+                {
+                    filteredGroupedEmployees[group.Key] = filteredEmployees;
+                }
+            }
+
+            return filteredGroupedEmployees;
+        }
