+        /// <summary>
+        /// 获取当月需要社保公积金退保的员工信息
+        /// </summary>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        public async Task<TableData<Dictionary<string, List<SocialSecurityRefundEmployeeDto>>>> GetEmployeesForSocialRefund(SocialSecurityRemind req)
+        {
+            var result = new TableData<Dictionary<string, List<SocialSecurityRefundEmployeeDto>>>();
+
+            // 获取时间范围
+            var now = req.QueryMonth ?? DateTime.Now;
+            var currentMonthStart = new DateTime(now.Year, now.Month, 1, 0, 0, 0, DateTimeKind.Local);
+            var currentMonthEnd = currentMonthStart.AddMonths(1).AddDays(-1);
+
+            // 获取所有候选人（离职或退保）的钉钉ID
+            var ddUserIds = await GetRefundCandidateDdUserIdsAsync(currentMonthStart, currentMonthEnd, req.Type);
+            if (!ddUserIds.Any())
+            {
+                result.Data = new Dictionary<string, List<SocialSecurityRefundEmployeeDto>>();
+                result.Count = 0;
+                return result;
+            }
+
+            // 构建钉钉用户查询，并应用动态过滤器（姓名、部门、劳务关系）
+            var dingTalkUsersQuery = UnitWork.Find<DingTalkUserDetail>(x => ddUserIds.Contains(x.UserId));
+            dingTalkUsersQuery = await ApplyQueryFiltersAsync(dingTalkUsersQuery, req);
+
+            //  获取最终符合条件的钉钉用户
+            var allDingTalkUsers = await dingTalkUsersQuery.ToListAsync();
+
+            // 加载构建DTO所需的所有数据映射
+            var dataMaps = await LoadRefundDataMapsAsync(ddUserIds, allDingTalkUsers);
+
+            
+            var groupedEmployees = await BuildAndGroupRefundEmployeesAsync(ddUserIds, dataMaps,req);
+
+            // 根据退缴状态进行最终筛选
+            var filteredGroups = FilterRefundGroupsByPaymentStatus(groupedEmployees, req);
+
+            int totalCount = CalculateTotalCount(filteredGroups);
+            result.Data = filteredGroups;
+            result.Count = totalCount;
+            return result;
+        }
