+        /// <summary>
+        /// 获取所有候选人（离职或退保）的钉钉ID
+        /// </summary>
+        /// <param name="monthStart"></param>
+        /// <param name="monthEnd"></param>
+        /// <param name="type"></param>
+        /// <returns></returns>
+        private async Task<List<string>> GetRefundCandidateDdUserIdsAsync(DateTime monthStart, DateTime monthEnd, SocialsecurityTypeEnums type)
+        {
+            var ddUserIdsSet = new HashSet<string>();
+
+            // 获取社保/公积金停缴的员工
+            var paymentEndUserIds = await GetPaymentEndDdUserIdsAsync(monthStart, monthEnd, type);
+            ddUserIdsSet.UnionWith(paymentEndUserIds);
+
+            // 获取离职的员工 (包含排除未来退保的逻辑)
+            var resignedUserIds = await GetResignedDdUserIdsAsync(monthStart, monthEnd, type);
+            ddUserIdsSet.UnionWith(resignedUserIds);
+
+            return ddUserIdsSet.ToList();
+            
+        }
+        /// <summary>
+        /// 获取社保/公积金停缴的员工 DDUserId 
+        /// </summary>
+        /// <param name="monthStart"></param>
+        /// <param name="monthEnd"></param>
+        /// <param name="type"></param>
+        /// <returns></returns>
+        /// <summary>
+        /// 获取社保/公积金停缴的员工 DDUserId
+        /// </summary>
+        private async Task<List<string>> GetPaymentEndDdUserIdsAsync(DateTime monthStart, DateTime monthEnd, SocialsecurityTypeEnums type)
+        {
+            var refundSocialsecurityRecords = await UnitWork.Find<UserSocialsecurity>(ss =>
+                (type == SocialsecurityTypeEnums.Socialsecurity && ss.SEndPaymentTime >= monthStart && ss.SEndPaymentTime <= monthEnd) ||
+                (type == SocialsecurityTypeEnums.Accumulationfunds && ss.PEndPaymentTime >= monthStart && ss.PEndPaymentTime <= monthEnd)
+            ).ToListAsync();
+
+            var paymentEndSystemUserIds = refundSocialsecurityRecords.Select(x => x.UserId).Distinct().ToList();
+
+            if (!paymentEndSystemUserIds.Any())
+            {
+                return new List<string>();
+            }
+
+            var ddBindUsers = await UnitWork.Find<DDBindUser>(x => paymentEndSystemUserIds.Contains(x.UserId)).ToListAsync();
+            return ddBindUsers.Select(x => x.DDUserId).Where(id => !string.IsNullOrEmpty(id)).ToList();
+        }
+        /// <summary>
+        /// 获取离职员工的 DDUserId (已排除未来停缴的人员)
+        /// </summary>
+        /// <param name="monthStart"></param>
+        /// <param name="monthEnd"></param>
+        /// <param name="type"></param>
+        /// <returns></returns>
+        private async Task<List<string>> GetResignedDdUserIdsAsync(DateTime monthStart, DateTime monthEnd, SocialsecurityTypeEnums type)
+        {
+            // 根据类型查询离职员工
+            List<DingTalkUserDetail> resignedDdUsers;
+            if (type == SocialsecurityTypeEnums.Socialsecurity)
+            {
+                // 社保：查询当月离职的员工
+                resignedDdUsers = await UnitWork.Find<DingTalkUserDetail>(x =>
+                    x.LeaveDate >= monthStart &&
+                    x.LeaveDate <= monthEnd
+                ).ToListAsync();
+            }
+            else
+            {
+                // 公积金：区分15号节点
+                var midMonth = new DateTime(monthStart.Year, monthStart.Month, 15, 23, 59, 59, DateTimeKind.Local);
+                var lastMonthStart = monthStart.AddMonths(-1);
+                var lastMonth16th = new DateTime(lastMonthStart.Year, lastMonthStart.Month, 16, 0, 0, 0, DateTimeKind.Local);
+                var lastMonthEnd = monthStart.AddDays(-1);
+
+                resignedDdUsers = await UnitWork.Find<DingTalkUserDetail>(x =>
+                    // 当月1号至15号离职 (当月停缴)
+                    (x.LeaveDate >= monthStart && x.LeaveDate <= midMonth) ||
+                    // 上月16号至上月末离职 (次月停缴，即本月)
+                    (x.LeaveDate >= lastMonth16th && x.LeaveDate <= lastMonthEnd)
+                ).ToListAsync();
+            }
+
+            var resignedDdUserIds = resignedDdUsers.Select(x => x.UserId).Where(id => !string.IsNullOrEmpty(id)).ToList();
+            if (!resignedDdUserIds.Any())
+            {
+                return new List<string>();
+            }
+
+            // 排除“退保时间在未来”的员工
+            var resignedSystemUserIds = await UnitWork.Find<DDBindUser>(x => resignedDdUserIds.Contains(x.DDUserId))
+                                                      .Select(x => x.UserId).ToListAsync();
+
+            if (!resignedSystemUserIds.Any())
+            {
+                return resignedDdUserIds;
+            }
+
+            // 查询那些当月离职但社保/公积金截止时间在下个月及以后的系统 UserId
+            var futurePaymentSystemUserIds = await UnitWork.Find<UserSocialsecurity>(ss =>
+                resignedSystemUserIds.Contains(ss.UserId) &&
+                (
+                    (type == SocialsecurityTypeEnums.Socialsecurity && ss.SEndPaymentTime > monthEnd) ||
+                    (type == SocialsecurityTypeEnums.Accumulationfunds && ss.PEndPaymentTime > monthEnd)
+                )
+            ).Select(x => x.UserId).ToListAsync();
+
+            if (futurePaymentSystemUserIds.Any())
+            {
+                var futurePaymentDdUserIds = await UnitWork.Find<DDBindUser>(x => futurePaymentSystemUserIds.Contains(x.UserId))
+                                                           .Select(x => x.DDUserId).ToListAsync();
+
+                // 从候选列表中移除这些 ID
+                return resignedDdUserIds.Except(futurePaymentDdUserIds).ToList();
+            }
+
+            return resignedDdUserIds;
+        }
+        /// <summary>
+        /// 应用动态查询过滤器（部门、姓名、劳务关系）
+        /// </summary>
+        /// <param name="query"></param>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        private async Task<IQueryable<DingTalkUserDetail>> ApplyQueryFiltersAsync(IQueryable<DingTalkUserDetail> query, SocialSecurityRemind req)
+        {
+            // 筛选部门或姓名
+            if (!string.IsNullOrEmpty(req.DepartOrName))
+            {
+                query = query.Where(x =>
+                    (x.DepartmentCode != null && x.DepartmentCode.Contains(req.DepartOrName)) ||
+                    (x.Name != null && x.Name.Contains(req.DepartOrName)));
+            }
+
+            // 筛选劳务关系
+            if (!string.IsNullOrEmpty(req.ServiceRelations)&& req.ServiceRelations!= "All")
+            {
+                // 获取符合劳务关系条件的系统用户ID
+                var usersWithRelation = await UnitWork.Find<User>(x =>
+                    !string.IsNullOrEmpty(x.ServiceRelations) &&
+                    x.ServiceRelations.Contains(req.ServiceRelations)
+                ).ToListAsync();
+                var systemUserIdsWithRelation = usersWithRelation.Select(x => x.Id).ToList();
+
+                // 获取这些系统用户对应的钉钉用户ID
+                var ddBindUsersWithRelation = await UnitWork.Find<DDBindUser>(x =>
+                    systemUserIdsWithRelation.Contains(x.UserId)
+                ).ToListAsync();
+                var ddUserIdsWithRelation = ddBindUsersWithRelation.Select(x => x.DDUserId).ToList();
+
+                // 应用筛选
+                query = query.Where(x => ddUserIdsWithRelation.Contains(x.UserId));
+            }
+
+            return query;
+        }
