+        /// <summary>
+        /// 加载构建DTO所需的所有数据映射
+        /// </summary>
+        /// <param name="allCandidateDdUserIds"></param>
+        /// <param name="filteredDingTalkUsers"></param>
+        /// <returns></returns>
+        private async Task<RefundDataMaps> LoadRefundDataMapsAsync(List<string> allCandidateDdUserIds, List<DingTalkUserDetail> filteredDingTalkUsers)
+        {
+            // 钉钉ID -> 钉钉用户 (已过滤)
+            var ddUserIdToUserMap = filteredDingTalkUsers.ToDictionary(x => x.UserId, x => x);
+
+            // 获取所有候选人（未过滤）的系统ID映射
+            var ddBindUsersAll = await UnitWork.Find<DDBindUser>(x => allCandidateDdUserIds.Contains(x.DDUserId)).ToListAsync();
+            // 钉钉ID -> 系统ID
+            var ddUserIdToSystemUserIdMap = ddBindUsersAll.ToDictionary(x => x.DDUserId, x => x.UserId);
+
+            // 获取所有相关的系统用户ID
+            var systemUserIdsAll = ddBindUsersAll.Select(x => x.UserId).Distinct().ToList();
+
+            // 系统ID -> 社保/公积金列表
+            var accounts = await UnitWork.Find<UserRegisterApply>(x => allCandidateDdUserIds.Contains(x.DDUserId)).Select(x=>x.Account).ToListAsync();
+
+            var userSocialsecurities = await UnitWork.Find<UserSocialsecurity>(x => accounts.Contains(x.Account)).ToListAsync();
+            var userIdToSocialsecurityMap = userSocialsecurities.GroupBy(x => x.Account).ToDictionary(x => x.Key, x => x.ToList());
+
+            // 系统ID -> 用户详情 (离职原因)
+            var userDetails = await UnitWork.Find<UserDetail>(x => systemUserIdsAll.Contains(x.UserId)).ToListAsync();
+            var userIdToUserDetailMap = userDetails.ToDictionary(x => x.UserId, x => x);
+
+            // 系统ID -> 系统用户 (劳务关系)
+            var systemUsers = await UnitWork.Find<User>(x => systemUserIdsAll.Contains(x.Id)).ToListAsync();
+            var userIdToSystemUserMap = systemUsers.ToDictionary(x => x.Id, x => x);
+
+            return new RefundDataMaps(
+                ddUserIdToUserMap,
+                ddUserIdToSystemUserIdMap,
+                userIdToSocialsecurityMap,
+                userIdToUserDetailMap,
+                userIdToSystemUserMap
+            );
+        }
