+        private async Task<Dictionary<string, List<SocialSecurityRefundEmployeeDto>>> BuildAndGroupRefundEmployeesAsync(List<string> ddUserIds, RefundDataMaps maps, SocialSecurityRemind req)
+        {
+            var groupedEmployees = new Dictionary<string, List<SocialSecurityRefundEmployeeDto>>
+            {
+                [INTERNSHIP_GROUP_KEY] = new List<SocialSecurityRefundEmployeeDto>(),
+                [OTHER_GROUP_KEY] = new List<SocialSecurityRefundEmployeeDto>()
+            };
+
+            foreach (var ddUserId in ddUserIds)
+            {
+                // 如果用户被过滤器（姓名、劳务关系等）筛掉了，则跳过
+                if (!maps.DdUserIdToUserMap.TryGetValue(ddUserId, out var dingTalkUser))
+                    continue;
+
+                // 构建DTO
+                var employee = await BuildRefundEmployeeDtoAsync(dingTalkUser, maps,req);
+
+                // 添加到分组
+                AddRefundEmployeeToGroup(groupedEmployees, employee, dingTalkUser, maps);
+            }
+
+            // 对每个分组的员工列表按离职日期排序
+            foreach (var groupKey in groupedEmployees.Keys.ToList())
+            {
+                groupedEmployees[groupKey] = groupedEmployees[groupKey]
+                    .OrderBy(e => e.LeaveDate)
+                    .ToList();
+            }
+
+            RemoveEmptyInternshipGroup(groupedEmployees); // 移除空的实习生分组
+            return groupedEmployees;
+        }
