+            else
+            {
+                // 没有社保公积金记录时，创建默认的DTO，EndPaymentTime为当月1号
+                var currentMonthStart = new DateTime(DateTime.Now.Year, DateTime.Now.Month, 1, 0, 0, 0, DateTimeKind.Local);
+                employee.UserSocialSecurityDtos = new List<UserSocialSecurityDto>
+                {
+                    new UserSocialSecurityDto { EndPaymentTime = currentMonthStart }
