+                    UpdateTime = DateTime.Now,
+                    UpdateUserId = logUserId,
+                };
+                await UnitWork.AddAsync<UserSocialsecurity, int>(addSocialSecurityInfo);
+            }
+            else
+            {
+                foreach (var item in socialSecurityInfo)
+                {
+                    item.PBeginPaymentTime = transferInfo.BeginPaymentTime;
+                    if (transferType == TransferSocialSecurityTypeEnums.TransferLaborRelation)
+                    {
+                        item.PEndPaymentTime = transferInfo.EndPaymentTime;
+                    }
+                    // 更新社保信息
+                    item.UpdateTime = DateTime.Now;
+                    item.UpdateUserId = logUserId;
+                }
+                await UnitWork.BatchUpdateAsync(socialSecurityInfo.ToArray());
+            }
+        }
