+        /// <summary>
+        /// 批量修改社保公积金信息（缴纳列表）
+        /// </summary>
+        /// <param name="request"></param>
+        /// <returns></returns>
+        public async Task<string> BatchUpdateSocialFundInfoAdvancedV(BatchUpdateSocialFundRequest request)
+        {
+            try
+            {
+                // 获取当前登录用户信息
+                var loginContext = _auth.GetCurrentUser() ?? throw new CommonException(Define.LoginHasExpired, Define.INVALID_TOKEN);
+                var loginUser = loginContext.User;
+
+                // 验证和获取注册用户信息 (使用辅助方法)
+                var ddUserIds = request.EmployeeUpdates.Select(x => x.DDUserId).Distinct().ToList();
+                var (registeredUserMap, errorMessage) = await ValidateAndGetRegisteredUsers(ddUserIds);
+                if (registeredUserMap == null)
+                {
+                    return errorMessage; // 返回错误信息
+                }
+
+                // 过滤掉未注册的用户，只处理已注册的
+                request.EmployeeUpdates = request.EmployeeUpdates.Where(x => registeredUserMap.ContainsKey(x.DDUserId)).ToList();
+
+                // 验证必填字段和自动填充逻辑
+                var validationError = ValidateSocialFundUpdatesAsync(request, registeredUserMap);
+                if (!string.IsNullOrEmpty(validationError))
+                {
+                    return validationError;
+                }
+
+                // 批量获取所有已注册用户的现有数据
+                Dictionary<string, UserIdentification> accountToIdentificationMap;
+                Dictionary<string, List<UserSocialsecurity>> accountToSocialsecurityMap;
+                 (accountToIdentificationMap, accountToSocialsecurityMap) = await LoadExistingDataAsync(registeredUserMap);
+
+                // 记录修改前的数据用于操作日志
+                var beforeDataMap = BuildFundBeforeDataMap(request.EmployeeUpdates, registeredUserMap, accountToIdentificationMap, accountToSocialsecurityMap);
+
+                // 处理所有更新，并填充变更列表
+                var changes = new DatabaseChangeLists();
+                ProcessEmployeeUpdates(
+                    changes,
+                    request,
+                    registeredUserMap,
+                    accountToIdentificationMap,
+                    accountToSocialsecurityMap,
+                    loginUser
+                );
+
+                //  批量执行数据库操作
+                await ExecuteDatabaseChangesAsync(changes);
+
+                // 重新加载修改后的数据并记录操作日志
+                (accountToIdentificationMap, accountToSocialsecurityMap) = await LoadExistingDataAsync(registeredUserMap);
+                await RecordFundLogsAsync(request, registeredUserMap, beforeDataMap, accountToIdentificationMap, accountToSocialsecurityMap);
+
+                return ""; // 成功返回空字符串
+            }
+            catch (Exception ex)
+            {
+                return ex.Message;
+            }
+        }
