+        /// <summary>
+        /// 
+        /// </summary>
+        /// <param name="updates"></param>
+        /// <param name="registeredUserMap"></param>
+        /// <param name="identMap"></param>
+        /// <param name="socialMap"></param>
+        /// <returns></returns>
+        private static Dictionary<string, (UserIdentification Ident, List<UserSocialsecurity> Social)> BuildFundBeforeDataMap(
+            List<UpdateSocialFundRequest> updates, // 假设 DTO 类型
+            Dictionary<string, UserRegisterApply> registeredUserMap,
+            Dictionary<string, UserIdentification> identMap,
+            Dictionary<string, List<UserSocialsecurity>> socialMap)
+        {
+            return updates.ToDictionary(
+                updateRequest => updateRequest.DDUserId,
+
+                updateRequest =>
+                {
+                    var account = registeredUserMap[updateRequest.DDUserId].Account;
+
+                    var beforeIdent = identMap.ContainsKey(account)
+                        ? JsonConvert.DeserializeObject<UserIdentification>(JsonConvert.SerializeObject(identMap[account]))
+                        : null;
+
+                    var beforeSocial = socialMap.ContainsKey(account)
+                        ? JsonConvert.DeserializeObject<List<UserSocialsecurity>>(JsonConvert.SerializeObject(socialMap[account]))
+                        : null;
+
+                    return (beforeIdent, beforeSocial);
+                }
+            );
+        }
+
+        /// <summary>
+        /// 
+        /// </summary>
+        /// <param name="request"></param>
+        /// <param name="registeredUserMap"></param>
+        /// <param name="beforeDataMap"></param>
+        /// <param name="afterIdentMap"></param>
+        /// <param name="afterSocialMap"></param>
+        /// <returns></returns>
+        private async Task RecordFundLogsAsync(
+            BatchUpdateSocialFundRequest request,
+            Dictionary<string, UserRegisterApply> registeredUserMap,
+            Dictionary<string, (UserIdentification Ident, List<UserSocialsecurity> Social)> beforeDataMap,
+            Dictionary<string, UserIdentification> afterIdentMap,
+            Dictionary<string, List<UserSocialsecurity>> afterSocialMap)
+        {
+            foreach (var updateRequest in request.EmployeeUpdates)
+            {
+                var userRegister = registeredUserMap[updateRequest.DDUserId];
+                var account = userRegister.Account;
+
+                // 获取修改后数据
+                var afterIdent = afterIdentMap.GetValueOrDefault(account);
+                var afterSocial = afterSocialMap.GetValueOrDefault(account);
+                var afterData = new { Identification = afterIdent, SocialSecurity = afterSocial };
+
+                // 获取修改前数据
+                var hasBeforeData = beforeDataMap.TryGetValue(updateRequest.DDUserId, out var beforeDataTuple);
+                var beforeDataObj = hasBeforeData ? new { Identification = beforeDataTuple.Ident, SocialSecurity = beforeDataTuple.Social } : null;
+
+                bool wasPreviouslyConfirmed = false;
+                if (hasBeforeData && beforeDataTuple.Social != null)
+                {
+                    var records = beforeDataTuple.Social.Where(x => x.Type == request.Type);
+
+                    if (request.Type == SocialsecurityTypeEnums.Socialsecurity)
+                    {
+                        wasPreviouslyConfirmed = records.Any(r => r.SIsPay == "Y" || r.SIsEnd == "Y");
+                    }
+                    else if (request.Type == SocialsecurityTypeEnums.Accumulationfunds)
+                    {
+                        wasPreviouslyConfirmed = records.Any(r => r.PIsPay == "Y" || r.PIsEnd == "Y");
+                    }
+                }
+
+                var changeResult = _socialSecurityOperationLogHelper.GenerateUpdateResult(beforeDataObj, afterData);
+                var dto = new RecordUpdateLogDto
+                {
+                    DDUserId = updateRequest.DDUserId,
+                    UserId = updateRequest.UserId,
+                    Account = account,
+                    Name = userRegister.Name,
+                    BeforeData = beforeDataObj,
+                    AfterData = afterData,
+                    Result = "修改成功",
+                    Type = request.Type,
+                    UpdateType = PaymentOrRefundEnums.Payment,
+                    ChangeResult = changeResult,
+                    IsNeedRemind = wasPreviouslyConfirmed && changeResult.HasSubstantiveChange
+
+                };
+                await RecordOperationLogAsync(dto);
+            }
+        }
