+        /// <summary>
+        /// 批量加载现有数据
+        /// </summary>
+        /// <param name="registeredUserMap"></param>
+        /// <returns></returns>
+        private async Task<(Dictionary<string, UserIdentification>, Dictionary<string, List<UserSocialsecurity>>)>
+            LoadExistingDataAsync(Dictionary<string, UserRegisterApply> registeredUserMap)
+        {
+            var registeredAccounts = registeredUserMap.Values.Select(x => x.Account).ToList();
+
+            var existingIdentifications = await UnitWork.Find<UserIdentification>(x => registeredAccounts.Contains(x.Account)).ToListAsync();
+            var accountToIdentificationMap = existingIdentifications
+                .GroupBy(x => x.Account)
+                .ToDictionary(g => g.Key, g => g.OrderByDescending(x => x.Id).FirstOrDefault());
+
+            var existingSocialsecurities = await UnitWork.Find<UserSocialsecurity>(x => registeredAccounts.Contains(x.Account)).ToListAsync();
+            var accountToSocialsecurityMap = existingSocialsecurities
+                .GroupBy(x => x.Account)
+                .ToDictionary(g => g.Key, g => g.ToList());
+
+            return (accountToIdentificationMap, accountToSocialsecurityMap);
+        }
