+            {
+                var userRegister = registeredUserMap[updateRequest.DDUserId];
+                var account = userRegister.Account;
+                var systemUserId = updateRequest.UserId;
+                var userName = userRegister.Name;
+                accountToIdentificationMap.TryGetValue(account, out var currentIdentification);
