+                    currentIdentification,
+                    currentSecuritiesForUser,
+                    systemUserId,
+                    account,
+                    userName,
+                    loginUser);
+
+                // 处理身份证更新
+                ProcessIdentificationUpdate(
+                    changes,
+                    updateRequest,
+                    accountToIdentificationMap,
+                    systemUserId,
+                    account,
+                    userName);
+
+                // 处理社保/公积金更新
+                ProcessSocialFundUpdate(
+                    changes,
+                    updateRequest,
+                    request.Type,
+                    accountToSocialsecurityMap,
+                    systemUserId,
+                    account,
+                    userName,
+                    loginUser,
+                    hasSubstantiveChange);
