+        {
+            try
+            {
+                //  获取当前登录用户信息
+                var loginContext = _auth.GetCurrentUser() ?? throw new CommonException(Define.LoginHasExpired, Define.INVALID_TOKEN);
+                var loginUser = loginContext.User;
+
+                // 验证和获取注册用户信息
+                var ddUserIds = request.EmployeeUpdates.Select(x => x.DDUserId).Distinct().ToList();
+                var (registeredUserMap, errorMessage) = await ValidateAndGetRegisteredUsers(ddUserIds);
+                if (registeredUserMap == null)
+                {
+                    return errorMessage; // 返回错误信息
+                }
+                // 过滤掉未注册的用户
+                request.EmployeeUpdates = request.EmployeeUpdates.Where(x => registeredUserMap.ContainsKey(x.DDUserId)).ToList();
+
+                //  批量加载现有数据
+                var (accountToSocialsecurityMap, accountToUserDetailMap) = await LoadExistingRefundDataAsync(registeredUserMap);
+
+                // 记录修改前的数据（使用深拷贝避免引用问题）
+                var beforeDataMap = BuildRefundBeforeDataMap(request.EmployeeUpdates, registeredUserMap, accountToSocialsecurityMap, accountToUserDetailMap);
+
+                // 处理所有更新，并填充变更列表
