+        #region 辅助类和辅助方法
+        /// <summary>
+        /// 
+        /// </summary>
+        /// <param name="updates"></param>
+        /// <param name="registeredUserMap"></param>
+        /// <param name="socialMap"></param>
+        /// <param name="detailMap"></param>
+        /// <returns></returns>
+        private static Dictionary<string, (List<UserSocialsecurity> Social, UserDetail Detail)> BuildRefundBeforeDataMap(
+            List<UpdateSocialReFundRequest> updates,
+            Dictionary<string, UserRegisterApply> registeredUserMap,
+            Dictionary<string, List<UserSocialsecurity>> socialMap,
+            Dictionary<string, UserDetail> detailMap)
+        {
+            var map = new Dictionary<string, (List<UserSocialsecurity>, UserDetail)>();
+
+            foreach (var updateRequest in updates)
+            {
+                var account = registeredUserMap[updateRequest.DDUserId].Account;
+
+                // 使用 JsonConvert 进行深拷贝
+                var beforeSocial = socialMap.ContainsKey(account)
+                    ? JsonConvert.DeserializeObject<List<UserSocialsecurity>>(JsonConvert.SerializeObject(socialMap[account]))
+                    : null;
+
+                var beforeDetail = detailMap.ContainsKey(account)
+                    ? JsonConvert.DeserializeObject<UserDetail>(JsonConvert.SerializeObject(detailMap[account]))
+                    : null;
+
+                // 使用 Account 作为 Key (保持原逻辑一致性)
+                map[account] = (beforeSocial, beforeDetail);
+            }
+            return map;
+        }
+        /// <summary>
+        /// 
+        /// </summary>
+        /// <param name="request"></param>
+        /// <param name="registeredUserMap"></param>
+        /// <param name="beforeDataMap"></param>
+        /// <param name="afterSocialMap"></param>
+        /// <param name="afterDetailMap"></param>
+        /// <returns></returns>
+        private async Task RecordRefundLogsAsync(
+            BatchUpdateSocialReFundRequest request,
+            Dictionary<string, UserRegisterApply> registeredUserMap,
+            Dictionary<string, (List<UserSocialsecurity> Social, UserDetail Detail)> beforeDataMap,
+            Dictionary<string, List<UserSocialsecurity>> afterSocialMap,
+            Dictionary<string, UserDetail> afterDetailMap)
+        {
+            foreach (var updateRequest in request.EmployeeUpdates)
+            {
+                var userRegister = registeredUserMap[updateRequest.DDUserId];
+                var account = userRegister.Account;
+
+                // 获取修改后数据
+                var afterSocial = afterSocialMap.GetValueOrDefault(account);
+                var afterDetail = afterDetailMap.GetValueOrDefault(account);
+                var afterData = new { SocialSecurity = afterSocial, UserDetail = afterDetail };
+
+                // 获取修改前数据 (强类型，无需反射)
+                var hasBeforeData = beforeDataMap.TryGetValue(account, out var beforeDataTuple);
+                var beforeDataObj = hasBeforeData ? new { SocialSecurity = beforeDataTuple.Social, UserDetail = beforeDataTuple.Detail } : null;
+
+                bool wasPreviouslyConfirmed = false;
+                if (hasBeforeData && beforeDataTuple.Social != null)
+                {
+                    var targetRecord = beforeDataTuple.Social.FirstOrDefault(x => x.Type == request.Type);
+                    if (targetRecord != null)
+                    {
+                        bool isSocialEnd = request.Type == SocialsecurityTypeEnums.Socialsecurity && targetRecord.SIsEnd == "Y";
+                        bool isFundEnd = request.Type == SocialsecurityTypeEnums.Accumulationfunds && targetRecord.PIsEnd == "Y";
+
+                        wasPreviouslyConfirmed = isSocialEnd || isFundEnd;
+                    }
+                }
+
+                var changeResult = _socialSecurityOperationLogHelper.GenerateUpdateResult(beforeDataObj, afterData);
+                var dto = new RecordUpdateLogDto
+                {
+                    DDUserId = updateRequest.DDUserId,
+                    UserId = updateRequest.UserId,
+                    Account = account,
+                    Name = userRegister.Name,
+                    BeforeData = beforeDataObj,
+                    AfterData = afterData,
+                    Result = "退缴修改成功",
+                    Type = request.Type,
+                    UpdateType = PaymentOrRefundEnums.Refund,
+                    ChangeResult = changeResult,
+                    IsNeedRemind = wasPreviouslyConfirmed && changeResult.HasSubstantiveChange
+
+                };
+                await RecordOperationLogAsync(dto);
+            }
+        }
