+        private async Task<(Dictionary<string, List<UserSocialsecurity>>, Dictionary<string, UserDetail>)>
+            LoadExistingRefundDataAsync(Dictionary<string, UserRegisterApply> registeredUserMap)
+        {
+            var registeredAccounts = registeredUserMap.Values.Select(x => x.Account).ToList();
+
+            var existingSocialsecurities = await UnitWork.Find<UserSocialsecurity>(x => registeredAccounts.Contains(x.Account)).ToListAsync();
+            var accountToSocialsecurityMap = existingSocialsecurities.GroupBy(x => x.Account).ToDictionary(g => g.Key, g => g.ToList());
