+        /// <summary>
+        /// 验证社保公积金更新请求的必填字段和自动填充逻辑
+        /// </summary>
+        /// <param name="request">批量更新请求</param>
+        /// <param name="registeredUserMap">已注册用户映射</param>
+        /// <returns>验证错误信息，如果验证通过返回空字符串</returns>
+        private static string ValidateSocialFundUpdatesAsync(BatchUpdateSocialFundRequest request, Dictionary<string, UserRegisterApply> registeredUserMap)
+        {
+            var validationErrors = new List<string>();
+            
+            for (int i = 0; i < request.EmployeeUpdates.Count; i++)
+            {
+                var updateRequest = request.EmployeeUpdates[i];
+                var userRegister = registeredUserMap[updateRequest.DDUserId];
+                
+                // 验证身份证和身份证地址必填
+                if (string.IsNullOrWhiteSpace(updateRequest.IdCard))
+                {
+                    validationErrors.Add($"员工【{userRegister.Name}】的身份证号不能为空");
+                }
+                if (string.IsNullOrWhiteSpace(updateRequest.IdCardAddress))
+                {
+                    validationErrors.Add($"员工【{userRegister.Name}】的身份证地址不能为空");
+                }
+                
+                // 根据类型处理自动填充和验证逻辑
+                if (request.Type == SocialsecurityTypeEnums.Socialsecurity)
+                {
+                    // 社保类型：如果社保电脑号为空，自动填充为"无"
+                    if (string.IsNullOrWhiteSpace(updateRequest.SocialSecurityAccount))
+                    {
+                        updateRequest.SocialSecurityAccount = "无";
+                    }
+                }
+                else if (request.Type == SocialsecurityTypeEnums.Accumulationfunds && string.IsNullOrWhiteSpace(updateRequest.SocialSecurityAccount))
+                {
+                    // 公积金类型：如果社保电脑号为空，自动填充为"无"
+                        updateRequest.SocialSecurityAccount = "无";
+                    // 当SocialSecurityAccount为空时，验证公积金银行和公积金银行账号必填
+                    if (string.IsNullOrWhiteSpace(updateRequest.ProvidentFundBank))
+                    {
+                        validationErrors.Add($"员工【{userRegister.Name}】的公积金银行不能为空");
+                    }
+                    if (string.IsNullOrWhiteSpace(updateRequest.ProvidentFundBankAccount))
+                    {
+                        validationErrors.Add($"员工【{userRegister.Name}】的公积金银行账号不能为空");
+                    }
+                    
+                    // 如果SocialSecurityAccount有填写，不需要验证ProvidentFundBank和ProvidentFundBankAccount
+                }
+            }
+            
+            // 返回验证错误信息，如果没有错误返回空字符串
+            return validationErrors.Any() ? string.Join("; ", validationErrors) : "";
+        }
+        /// <summary>
+        /// 统一处理 UserSocialsecurity 记录的创建或更新逻辑。
+        /// 通过参数对象 ProcessSocialsecurityRecordParams 减少方法签名参数数量。
+        /// </summary>
+        /// <param name="p"></param>
+        private void ProcessSocialsecurityRecord(ProcessSocialsecurityRecordParams p)
+        {
+            // 获取当前时间和登录用户ID
+            var now = DateTime.Now;
+            var updateUserId = p.LoginUser?.Id;
+            
+            // 查找所有同类型的记录，不再按UpdateId匹配单条记录
+            var socialsecurityRecords = p.CurrentSecurities?.Where(x => x.Type == p.Type).ToList();
+            
+            if (socialsecurityRecords == null || socialsecurityRecords.Count == 0)
+            {
+                // 没有找到同类型记录，无论是否有字段更新，都创建新记录以保存处理人和处理时间
+                // 记录原来没有标注是社保公积金的记录，然后删掉 
+                var oldUnspecifiedTypeRecords = p.CurrentSecurities?.Where(x => x.Type != SocialsecurityTypeEnums.Socialsecurity && x.Type != SocialsecurityTypeEnums.Accumulationfunds).ToList();
+                if (oldUnspecifiedTypeRecords != null && oldUnspecifiedTypeRecords.Any())
+                {
+                    p.DelSocialsecurityList.AddRange(oldUnspecifiedTypeRecords);
+                    // 从 currentSecurities 中移除这些记录，以免后续逻辑再次处理或导致冲突
+                    p.CurrentSecurities.RemoveAll(x => oldUnspecifiedTypeRecords.Contains(x));
+                }
+
+                // 从旧的未指定Type的记录中获取一些默认值，避免丢失
+                var defaultRecord = oldUnspecifiedTypeRecords?.FirstOrDefault();
+                // 创建新的记录
+                var newRecord = new UserSocialsecurity
+                {
+                    UserId = p.UserId,
+                    Account = p.Account,
+                    Name = p.Name,
+                    CreateTime = now,
+                    Type = p.Type,
+                    // 默认从 defaultRecord 获取一些可继承的基础信息，避免丢失
+                    Grade = defaultRecord?.Grade ?? "",
+                    SocialsecurityAccount = defaultRecord?.SocialsecurityAccount ?? "", // 可能是旧的未分类的账号
+                    Bank = defaultRecord?.Bank ?? "",
+                    AttachmentId = defaultRecord?.AttachmentId,
+                    SIsPay = defaultRecord?.SIsPay,
+                    SIsEnd = defaultRecord?.SIsEnd,
+                    PIsPay = defaultRecord?.PIsPay,
+                    PIsEnd = defaultRecord?.PIsEnd,
+                    ProvidentFundBank = defaultRecord?.ProvidentFundBank,
+                    ProvidentFundBankAccount = defaultRecord?.ProvidentFundBankAccount,
+                    SBeginPaymentTime = defaultRecord?.SBeginPaymentTime,
+                    PEndPaymentTime = defaultRecord?.PEndPaymentTime,
+                };
+                ApplyInfoUpdateAuditFields(newRecord, p.OperationScene, now, updateUserId);
+                p.CreateAction(newRecord); // 执行特定于创建的初始化
+                p.AddSocialsecurityList.Add(newRecord);
+            }
+            else
+            {
+                // 更新所有同类型的记录
+                foreach (var record in socialsecurityRecords)
+                {
+                    p.UpdateAction(record); // 执行特定于更新的操作
+                    
+                    // 只有存在实质性变更时，才需要打回已确认状态并更新时间
+                    if (p.HasSubstantiveChange && p.Type == SocialsecurityTypeEnums.Socialsecurity)
+                    {
+                        if (record.SIsPay == "Y")
+                        {
+                            record.SIsPay = "N";
+                        }
+                        if (record.SIsEnd == "Y")
+                        {
+                            record.SIsEnd = "N";
+                        }
+                    }
+                    else if (p.HasSubstantiveChange && p.Type == SocialsecurityTypeEnums.Accumulationfunds)
+                    {
+                        if (record.PIsPay == "Y" )
+                        {
+                            record.PIsPay = "N";
+                        }
+                        if (record.PIsEnd == "Y")
+                        {
+                            record.PIsEnd = "N";
+                        }
+                    }
+                    
+                    // 设置更新时间和更新用户ID
+                    ApplyInfoUpdateAuditFields(record, p.OperationScene, now, updateUserId);
+                    p.UpdateSocialsecurityList.Add(record);
+                }
+            }
+        }
