+        /// <summary>
+        /// 处理特定类型的社保/公积金记录
+        /// </summary>
+        /// <param name="type"></param>
+        /// <param name="confirmType"></param>
+        /// <param name="request"></param>
+        /// <param name="context"></param>
+        /// <param name="addList"></param>
+        /// <param name="updateList"></param>
+        /// <param name="loginUser"></param>
+        private void ProcessSocialsecurityType(
+            SocialsecurityTypeEnums type,
+            SocialsecurityTypeEnums confirmType,
+            BatchConfirmPaymentOrRefundRequest request,
+            SocialsecurityProcessingContext context,
+            List<UserSocialsecurity> addList,
+            List<UserSocialsecurity> updateList,
+            User loginUser = null)
+        {
+            // 获取当前时间和登录用户ID
+            var now = DateTime.Now;
+            var updateUserId = loginUser?.Id;
+            // 如果请求中指定的确认类型不包含当前处理类型，则跳过
+            if (request.ConfirmType != confirmType)
+            {
+                return;
+            }
+            // 筛选出当前账户中与当前 type 匹配的现有记录
+            var existingRecords = context.CurrentAccountSecurities.Where(x => x.Type == type).ToList();
+            if (existingRecords.Any())
+            {
+                // 验证是否已经操作过
+                foreach (var record in existingRecords)
+                {
+                    bool isPaid = request.PaymentOrRefund == PaymentOrRefundEnums.Payment &&
+                                 ((type == SocialsecurityTypeEnums.Socialsecurity && record.SIsPay == "Y") ||
+                                  (type == SocialsecurityTypeEnums.Accumulationfunds && record.PIsPay == "Y"));
+
+                    bool isRefunded = request.PaymentOrRefund == PaymentOrRefundEnums.Refund &&
+                                     ((type == SocialsecurityTypeEnums.Socialsecurity && record.SIsEnd == "Y") ||
+                                      (type == SocialsecurityTypeEnums.Accumulationfunds && record.PIsEnd == "Y"));
+
+                    if (isPaid)
+                        throw new ArgumentException($"员工 {context.UserName} 已操作缴纳,请重新操作");
+
+                    if (isRefunded)
+                        throw new ArgumentException($"员工 {context.UserName} 已操作退缴,请重新操作");
+                }
+                //验证是否已经登记过
+                var hasRegistered = context.CurrentAccountSecurities.Any(record =>
+                    record.Type == type &&
+                    HasRegisteredForScene(record, request.PaymentOrRefund));
+
+                if (!hasRegistered)
+                {
+                    throw new ArgumentException($"员工 {context.UserName} 的{(type == SocialsecurityTypeEnums.Socialsecurity ? "社保" : "公积金")}信息尚未登记，请先登记后再进行确认操作");
+                }
+                // 如果存在现有记录，则更新它们
+                foreach (var record in existingRecords)
+                {
+                    ApplyPaymentOrRefundStatus(record, request.PaymentOrRefund);
+                    // 设置更新时间和更新用户ID
+                    ApplyConfirmAuditFields(record, request.PaymentOrRefund, now, updateUserId);
+                    updateList.Add(record);
+                }
+            }
+            else
+            {
+                // 如果不存在现有记录（即第一次处理该类型的记录），则创建新记录
+                var newRecord = new UserSocialsecurity
+                {
+                    UserId = context.SystemUserId,          // 从上下文获取 UserId
+                    Account = context.Account,              // 从上下文获取 Account
+                    Name = context.UserName,                // 从上下文获取 UserName
+                    CreateTime = now,
+                    Type = type,
+                    AttachmentId = context.AttachmentIdForNewRecord // 从上下文获取 AttachmentId
+                };
+                ApplyConfirmAuditFields(newRecord, request.PaymentOrRefund, now, updateUserId);
+                ApplyPaymentOrRefundStatus(newRecord, request.PaymentOrRefund);
+                addList.Add(newRecord);
+            }
+        }
