+        /// <summary>
+        /// 更新操作日志的IsNeedRemind状态
+        /// </summary>
+        /// <param name="request"></param>
+        /// <param name="ddUserIds"></param>
+        /// <returns></returns>
+        private async Task UpdateOperationLogRemindStatusAsync(BatchConfirmPaymentOrRefundRequest request, List<string> ddUserIds)
+        {
+            try
+            {
+                // 获取需要更新的操作日志
+                var operationLogs = await UnitWork.Find<SocialsecurityOperationLog>(x => 
+                    ddUserIds.Contains(x.DDUserId) && 
+                    x.IsNeedRemind &&
+                    x.Type == request.ConfirmType && // 匹配确认类型
+                    x.UpdateType == request.PaymentOrRefund // 匹配缴纳/退缴类型
+                ).ToListAsync();
+
+                if (operationLogs.Any())
+                {
+                    // 更新IsNeedRemind为true
+                    foreach (var log in operationLogs)
+                    {
+                        log.IsNeedRemind = false;
+                        log.Result = $"已重新确认{GetPaymentOrRefundDescription(request.PaymentOrRefund)}";
+                    }
+
+                    await UnitWork.BatchUpdateAsync(operationLogs.ToArray());
+                    await UnitWork.SaveAsync();
+                }
+            }
+            catch (Exception ex)
+            {
+                // 记录错误但不抛出异常，避免影响主流程
+                Console.WriteLine($"更新操作日志提醒状态时发生错误: {ex.Message}");
+            }
+        }
