+        /// <summary>
+        /// 判断员工（特别是实习生）是否应包含在内
+        /// </summary>
+        /// <param name="employee"></param>
+        /// <param name="maps"></param>
+        /// <param name="req"></param>
+        /// <param name="monthStart"></param>
+        /// <param name="monthEnd"></param>
+        /// <returns></returns>
+        private bool ShouldIncludeEmployee(
+            SocialSecurityEmployeeDto employee,
+            EmployeeDataMaps maps,
+            SocialSecurityRemind req,
+            DateTime monthStart,
+            DateTime monthEnd)
+        {
+            // 非实习生，默认包含
+            if (!employee.IsInternship)
+            {
+                return true;
+            }
+
+            // --- 以下是实习生的特殊处理逻辑 ---
+
+            var account= UnitWork.Find<UserRegisterApply>(x => x.DDUserId == employee.DDUserid).Select(x=>x.Account).FirstOrDefault();
+            // 找不到社保/公积金记录，包含
+            if (!maps.UserIdToSocialsecurityMap.TryGetValue(account, out var socialsecurities))
+            {
+                return true;
+            }
+
+            bool shouldInclude = false; // 实习生默认不包含，除非满足条件
+
+            if (req.Type == SocialsecurityTypeEnums.Socialsecurity)
+            {
+                var record = socialsecurities
+                     .Where(x => x.Type == SocialsecurityTypeEnums.Socialsecurity)
+                     .OrderByDescending(x => x.Id) 
+                     .FirstOrDefault();
+                // 如果没有社保记录，或者没有设置开始时间，则包含
+                shouldInclude = !record?.SBeginPaymentTime.HasValue ?? true;
+            }
+            else if (req.Type == SocialsecurityTypeEnums.Accumulationfunds)
+            {
+                var record = socialsecurities
+                     .Where(x => x.Type == SocialsecurityTypeEnums.Accumulationfunds)
+                     .OrderByDescending(x => x.Id) 
+                     .FirstOrDefault();
+                // 如果没有公积金记录，或者没有设置开始时间，则包含
+                shouldInclude = !record?.PBeginPaymentTime.HasValue ?? true;
+            }
+
+            // 如果已被标记为包含（即没有开始时间），则直接返回
+            if (shouldInclude)
+            {
+                return true;
+            }
+
+            // 如果有开始时间（shouldInclude=false），则检查开始时间是否在本月
+            foreach (var ss in socialsecurities)
+            {
+                if ((req.Type == SocialsecurityTypeEnums.Socialsecurity && ss.SBeginPaymentTime.HasValue && ss.SBeginPaymentTime.Value >= monthStart && ss.SBeginPaymentTime.Value <= monthEnd) ||
+                    (req.Type == SocialsecurityTypeEnums.Accumulationfunds && ss.PBeginPaymentTime.HasValue && ss.PBeginPaymentTime.Value >= monthStart && ss.PBeginPaymentTime.Value <= monthEnd))
+                {
+                    shouldInclude = true;
+                    break;
+                }
+            }
+
+            // 检查是否存在非社保和非公积金的记录类型（原文逻辑）
+            if (!shouldInclude && socialsecurities.Any(x => x.Type != SocialsecurityTypeEnums.Socialsecurity && x.Type != SocialsecurityTypeEnums.Accumulationfunds))
+            {
+                shouldInclude = true;
+            }
+
+            return shouldInclude;
+        }
