+        /// <summary>
+        /// 根据缴纳状态对已分组的员工进行最终筛选
+        /// </summary>
+        /// <param name="groupedEmployees"></param>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        private static Dictionary<string, List<SocialSecurityEmployeeDto>> FilterGroupsByPaymentStatus(Dictionary<string, List<SocialSecurityEmployeeDto>> groupedEmployees, SocialSecurityRemind req)
+        {
+            // 0表示查询全部，不需要筛选
+            if (req.PaymentStatus == PaymentStatusEnums.全部)
+            {
+                return groupedEmployees;
+            }
+
+            var filteredGroupedEmployees = new Dictionary<string, List<SocialSecurityEmployeeDto>>();
+
+            foreach (var group in groupedEmployees)
+            {
+                var filteredEmployees = new List<SocialSecurityEmployeeDto>();
+                filteredEmployees.AddRange(group.Value.Where(employee => ShouldIncludeByPaymentStatus(employee, req)));
+
+
+                if (filteredEmployees.Count > 0)
+                {
+                    filteredGroupedEmployees[group.Key] = filteredEmployees;
+                }
+            }
+
+            return filteredGroupedEmployees;
+        }
+
+        /// <summary>
+        /// /判断单个员工是否满足“缴纳状态”过滤条件 (FilterGroupsByPaymentStatus 的子辅助)
+        /// </summary>
+        /// <param name="employee"></param>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        private static bool ShouldIncludeByPaymentStatus(SocialSecurityEmployeeDto employee, SocialSecurityRemind req)
+        {
+            if (req.Type == SocialsecurityTypeEnums.Socialsecurity)
+            {
+                if (req.PaymentStatus == PaymentStatusEnums.已缴纳)
+                {
+                    // 筛选SIsPay是Y的情况 (只要有一条记录是Y)
+                    return employee.UserSocialSecurityDtos != null &&
+                           employee.UserSocialSecurityDtos.Any(ss => ss.SIsPay == "Y");
+                }
+                else if (req.PaymentStatus == PaymentStatusEnums.未缴纳)
+                {
+                    // 筛选SIsPay是N或null (所有记录都不是Y)
+                    return employee.UserSocialSecurityDtos == null ||
+                           employee.UserSocialSecurityDtos.All(ss => ss.SIsPay != "Y");
+                }
+                else if (req.PaymentStatus == PaymentStatusEnums.已登记)
+                {
+                    // 筛选InfoUpdateTime和InfoUpdateUserId有值的情况 (只要有一条记录有值)
+                    return employee.UserSocialSecurityDtos != null &&
+                           employee.UserSocialSecurityDtos.Any(ss => ss.InfoUpdateTime.HasValue && !string.IsNullOrEmpty(ss.InfoUpdateUserId));
+                }
+                else if (req.PaymentStatus == PaymentStatusEnums.未登记)
+                {
+                    // 筛选InfoUpdateTime和InfoUpdateUserId为空的情况 (所有记录都为空)
+                    return employee.UserSocialSecurityDtos == null ||
+                           employee.UserSocialSecurityDtos.All(ss => !ss.InfoUpdateTime.HasValue || string.IsNullOrEmpty(ss.InfoUpdateUserId));
+                }
+            }
+            else if (req.Type == SocialsecurityTypeEnums.Accumulationfunds)
+            {
+                if (req.PaymentStatus == PaymentStatusEnums.已缴纳)
+                {
+                    // 筛选PIsPay是Y的情况 (只要有一条记录是Y)
+                    return employee.UserHousingFundDtos != null &&
+                           employee.UserHousingFundDtos.Any(hf => hf.PIsPay == "Y");
+                }
+                else if (req.PaymentStatus == PaymentStatusEnums.未缴纳)
+                {
+                    // 筛选PIsPay是N或null (所有记录都不是Y)
+                    return employee.UserHousingFundDtos == null ||
+                           employee.UserHousingFundDtos.All(hf => hf.PIsPay != "Y");
+                }
+                else if (req.PaymentStatus == PaymentStatusEnums.已登记)
+                {
+                    // 筛选InfoUpdateTime和InfoUpdateUserId有值的情况 (只要有一条记录有值)
+                    return employee.UserHousingFundDtos != null &&
+                           employee.UserHousingFundDtos.Any(hf => hf.InfoUpdateTime.HasValue && !string.IsNullOrEmpty(hf.InfoUpdateUserId));
+                }
+                else if (req.PaymentStatus == PaymentStatusEnums.未登记)
+                {
+                    // 筛选InfoUpdateTime和InfoUpdateUserId为空的情况 (所有记录都为空)
+                    return employee.UserHousingFundDtos == null ||
+                           employee.UserHousingFundDtos.All(hf => !hf.InfoUpdateTime.HasValue || string.IsNullOrEmpty(hf.InfoUpdateUserId));
+                }
+            }
+
+            return false; // 理论上不应该到这里
+        }
