+        /// <summary>
+        /// 获取所有候选人（离职或退保）的钉钉ID
+        /// </summary>
+        /// <param name="monthStart"></param>
+        /// <param name="monthEnd"></param>
+        /// <param name="type"></param>
+        /// <returns></returns>
+        private async Task<List<string>> GetRefundCandidateDdUserIdsAsync(DateTime monthStart, DateTime monthEnd, SocialsecurityTypeEnums type)
+        {
+            var ddUserIdsSet = new HashSet<string>();
+
+            // 获取社保/公积金停缴的员工
+            var paymentEndUserIds = await GetPaymentEndDdUserIdsAsync(monthStart, monthEnd, type);
+            ddUserIdsSet.UnionWith(paymentEndUserIds);
+
+            // 获取离职的员工 (包含排除未来退保的逻辑)
+            var resignedUserIds = await GetResignedDdUserIdsAsync(monthStart, monthEnd, type);
+            ddUserIdsSet.UnionWith(resignedUserIds);
+
+            return ddUserIdsSet.ToList();
+            
+        }
+        /// <summary>
+        /// 获取社保/公积金停缴的员工 DDUserId 
+        /// </summary>
+        /// <param name="monthStart"></param>
+        /// <param name="monthEnd"></param>
+        /// <param name="type"></param>
+        /// <returns></returns>
+        /// <summary>
+        /// 获取社保/公积金停缴的员工 DDUserId
+        /// </summary>
+        private async Task<List<string>> GetPaymentEndDdUserIdsAsync(DateTime monthStart, DateTime monthEnd, SocialsecurityTypeEnums type)
+        {
+            var refundSocialsecurityRecords = await UnitWork.Find<UserSocialsecurity>(ss =>
+                (type == SocialsecurityTypeEnums.Socialsecurity && ss.SEndPaymentTime >= monthStart && ss.SEndPaymentTime <= monthEnd) ||
+                (type == SocialsecurityTypeEnums.Accumulationfunds && ss.PEndPaymentTime >= monthStart && ss.PEndPaymentTime <= monthEnd)
+            ).ToListAsync();
+
+            var paymentEndSystemUserIds = refundSocialsecurityRecords.Select(x => x.UserId).Distinct().ToList();
+
+            if (!paymentEndSystemUserIds.Any())
+            {
+                return new List<string>();
+            }
+
+            var ddBindUsers = await UnitWork.Find<DDBindUser>(x => paymentEndSystemUserIds.Contains(x.UserId)).ToListAsync();
+            return ddBindUsers.Select(x => x.DDUserId).Where(id => !string.IsNullOrEmpty(id)).ToList();
+        }
+        /// <summary>
+        /// 获取离职员工的 DDUserId (已排除未来停缴的人员)
+        /// </summary>
+        /// <param name="monthStart"></param>
+        /// <param name="monthEnd"></param>
+        /// <param name="type"></param>
+        /// <returns></returns>
+        private async Task<List<string>> GetResignedDdUserIdsAsync(DateTime monthStart, DateTime monthEnd, SocialsecurityTypeEnums type)
+        {
+            // 根据类型查询离职员工
+            List<DingTalkUserDetail> resignedDdUsers;
+            if (type == SocialsecurityTypeEnums.Socialsecurity)
+            {
+                // 社保：查询当月离职的员工
+                resignedDdUsers = await UnitWork.Find<DingTalkUserDetail>(x =>
+                    x.LeaveDate >= monthStart &&
+                    x.LeaveDate <= monthEnd
+                ).ToListAsync();
+            }
+            else
+            {
+                // 公积金：区分15号节点
+                var midMonth = new DateTime(monthStart.Year, monthStart.Month, 15, 23, 59, 59, DateTimeKind.Local);
+                var lastMonthStart = monthStart.AddMonths(-1);
+                var lastMonth16th = new DateTime(lastMonthStart.Year, lastMonthStart.Month, 16, 0, 0, 0, DateTimeKind.Local);
+                var lastMonthEnd = monthStart.AddDays(-1);
+
+                resignedDdUsers = await UnitWork.Find<DingTalkUserDetail>(x =>
+                    // 当月1号至15号离职 (当月停缴)
+                    (x.LeaveDate >= monthStart && x.LeaveDate <= midMonth) ||
+                    // 上月16号至上月末离职 (次月停缴，即本月)
+                    (x.LeaveDate >= lastMonth16th && x.LeaveDate <= lastMonthEnd)
+                ).ToListAsync();
+            }
+
+            var resignedDdUserIds = resignedDdUsers.Select(x => x.UserId).Where(id => !string.IsNullOrEmpty(id)).ToList();
+            if (!resignedDdUserIds.Any())
+            {
+                return new List<string>();
+            }
+
+            // 排除“退保时间在未来”的员工
+            var resignedSystemUserIds = await UnitWork.Find<DDBindUser>(x => resignedDdUserIds.Contains(x.DDUserId))
+                                                      .Select(x => x.UserId).ToListAsync();
+
+            if (!resignedSystemUserIds.Any())
+            {
+                return resignedDdUserIds;
+            }
+
+            // 查询那些当月离职但社保/公积金截止时间在下个月及以后的系统 UserId
+            var futurePaymentSystemUserIds = await UnitWork.Find<UserSocialsecurity>(ss =>
+                resignedSystemUserIds.Contains(ss.UserId) &&
+                (
+                    (type == SocialsecurityTypeEnums.Socialsecurity && ss.SEndPaymentTime > monthEnd) ||
+                    (type == SocialsecurityTypeEnums.Accumulationfunds && ss.PEndPaymentTime > monthEnd)
+                )
+            ).Select(x => x.UserId).ToListAsync();
+
+            if (futurePaymentSystemUserIds.Any())
+            {
+                var futurePaymentDdUserIds = await UnitWork.Find<DDBindUser>(x => futurePaymentSystemUserIds.Contains(x.UserId))
+                                                           .Select(x => x.DDUserId).ToListAsync();
+
+                // 从候选列表中移除这些 ID
+                return resignedDdUserIds.Except(futurePaymentDdUserIds).ToList();
+            }
+
+            return resignedDdUserIds;
+        }
+        /// <summary>
+        /// 应用动态查询过滤器（部门、姓名、劳务关系）
+        /// </summary>
+        /// <param name="query"></param>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        private async Task<IQueryable<DingTalkUserDetail>> ApplyQueryFiltersAsync(IQueryable<DingTalkUserDetail> query, SocialSecurityRemind req)
+        {
+            // 筛选部门或姓名
+            if (!string.IsNullOrEmpty(req.DepartOrName))
+            {
+                query = query.Where(x =>
+                    (x.DepartmentCode != null && x.DepartmentCode.Contains(req.DepartOrName)) ||
+                    (x.Name != null && x.Name.Contains(req.DepartOrName)));
+            }
+
+            // 筛选劳务关系
+            if (!string.IsNullOrEmpty(req.ServiceRelations)&& req.ServiceRelations!= "All")
+            {
+                // 获取符合劳务关系条件的系统用户ID
+                var usersWithRelation = await UnitWork.Find<User>(x =>
+                    !string.IsNullOrEmpty(x.ServiceRelations) &&
+                    x.ServiceRelations.Contains(req.ServiceRelations)
+                ).ToListAsync();
+                var systemUserIdsWithRelation = usersWithRelation.Select(x => x.Id).ToList();
+
+                // 获取这些系统用户对应的钉钉用户ID
+                var ddBindUsersWithRelation = await UnitWork.Find<DDBindUser>(x =>
+                    systemUserIdsWithRelation.Contains(x.UserId)
+                ).ToListAsync();
+                var ddUserIdsWithRelation = ddBindUsersWithRelation.Select(x => x.DDUserId).ToList();
+
+                // 应用筛选
+                query = query.Where(x => ddUserIdsWithRelation.Contains(x.UserId));
+            }
+
+            return query;
+        }
+
+        /// <summary>
+        /// 加载构建DTO所需的所有数据映射
+        /// </summary>
+        /// <param name="allCandidateDdUserIds"></param>
+        /// <param name="filteredDingTalkUsers"></param>
+        /// <returns></returns>
+        private async Task<RefundDataMaps> LoadRefundDataMapsAsync(List<string> allCandidateDdUserIds, List<DingTalkUserDetail> filteredDingTalkUsers)
+        {
+            // 钉钉ID -> 钉钉用户 (已过滤)
+            var ddUserIdToUserMap = filteredDingTalkUsers.ToDictionary(x => x.UserId, x => x);
+
+            // 获取所有候选人（未过滤）的系统ID映射
+            var ddBindUsersAll = await UnitWork.Find<DDBindUser>(x => allCandidateDdUserIds.Contains(x.DDUserId)).ToListAsync();
+            // 钉钉ID -> 系统ID
+            var ddUserIdToSystemUserIdMap = ddBindUsersAll.ToDictionary(x => x.DDUserId, x => x.UserId);
+
+            // 获取所有相关的系统用户ID
+            var systemUserIdsAll = ddBindUsersAll.Select(x => x.UserId).Distinct().ToList();
+
+            // 系统ID -> 社保/公积金列表
+            var accounts = await UnitWork.Find<UserRegisterApply>(x => allCandidateDdUserIds.Contains(x.DDUserId)).Select(x=>x.Account).ToListAsync();
+
+            var userSocialsecurities = await UnitWork.Find<UserSocialsecurity>(x => accounts.Contains(x.Account)).ToListAsync();
+            var userIdToSocialsecurityMap = userSocialsecurities.GroupBy(x => x.Account).ToDictionary(x => x.Key, x => x.ToList());
+
+            // 系统ID -> 用户详情 (离职原因)
+            var userDetails = await UnitWork.Find<UserDetail>(x => systemUserIdsAll.Contains(x.UserId)).ToListAsync();
+            var userIdToUserDetailMap = userDetails.ToDictionary(x => x.UserId, x => x);
+
+            // 系统ID -> 系统用户 (劳务关系)
+            var systemUsers = await UnitWork.Find<User>(x => systemUserIdsAll.Contains(x.Id)).ToListAsync();
+            var userIdToSystemUserMap = systemUsers.ToDictionary(x => x.Id, x => x);
+
+            return new RefundDataMaps(
+                ddUserIdToUserMap,
+                ddUserIdToSystemUserIdMap,
+                userIdToSocialsecurityMap,
+                userIdToUserDetailMap,
+                userIdToSystemUserMap
+            );
+        }
+
+        /// <summary>
+        /// 遍历候选人，构建DTO并分组（异步版本，包含操作日志）
+        /// </summary>
+        /// <param name="ddUserIds"></param>
+        /// <param name="maps"></param>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        private async Task<Dictionary<string, List<SocialSecurityRefundEmployeeDto>>> BuildAndGroupRefundEmployeesAsync(List<string> ddUserIds, RefundDataMaps maps, SocialSecurityRemind req)
+        {
+            var groupedEmployees = new Dictionary<string, List<SocialSecurityRefundEmployeeDto>>
+            {
+                [INTERNSHIP_GROUP_KEY] = new List<SocialSecurityRefundEmployeeDto>(),
+                [OTHER_GROUP_KEY] = new List<SocialSecurityRefundEmployeeDto>()
+            };
+
+            foreach (var ddUserId in ddUserIds)
+            {
+                // 如果用户被过滤器（姓名、劳务关系等）筛掉了，则跳过
+                if (!maps.DdUserIdToUserMap.TryGetValue(ddUserId, out var dingTalkUser))
+                    continue;
+
+                // 构建DTO
+                var employee = await BuildRefundEmployeeDtoAsync(dingTalkUser, maps,req);
+
+                // 添加到分组
+                AddRefundEmployeeToGroup(groupedEmployees, employee, dingTalkUser, maps);
+            }
+
+            // 对每个分组的员工列表按离职日期排序
+            foreach (var groupKey in groupedEmployees.Keys.ToList())
+            {
+                groupedEmployees[groupKey] = groupedEmployees[groupKey]
+                    .OrderBy(e => e.LeaveDate)
+                    .ToList();
+            }
+
+            RemoveEmptyInternshipGroup(groupedEmployees); // 移除空的实习生分组
+            return groupedEmployees;
+        }
+
+        /// <summary>
+        /// 创建并填充单个员工 DTO（异步版本，包含操作日志）
+        /// </summary>
+        /// <param name="dingTalkUser"></param>
+        /// <param name="maps"></param>
+        /// <param name="req"></param>
+        /// <returns></returns>
+        private async Task<SocialSecurityRefundEmployeeDto> BuildRefundEmployeeDtoAsync(DingTalkUserDetail dingTalkUser, RefundDataMaps maps,SocialSecurityRemind req)
+        {
+            maps.DdUserIdToSystemUserIdMap.TryGetValue(dingTalkUser.UserId, out var systemUserId);
+            var userForType = new User();
+            var userDetail = new UserDetail();
+            if (!string.IsNullOrEmpty(systemUserId))
+            {
+                maps.UserIdToSystemUserMap.TryGetValue(systemUserId, out userForType);
+                maps.UserIdToUserDetailMap.TryGetValue(systemUserId, out userDetail);
+            }
+
+            string leaveReason = null;
+            string reasonDescription = null;
+            if (userDetail?.LeaveReason != null)
+            {
+                string description = EnumUtility.GetDescription(userDetail.LeaveReason);
+                if (description == "正常离职" || description == "非正常离职")
+                {
+                    leaveReason = ((int?)userDetail.LeaveReason)?.ToString();
+
+                    reasonDescription = description;
+                }
+            }
+
+            var employee = new SocialSecurityRefundEmployeeDto
+            {
+                Type = userForType?.TransferSocialSecurityFlag ?? "离职",
+                DDUserid = dingTalkUser.UserId,
+                UserId = string.IsNullOrEmpty(systemUserId) ? null : systemUserId.ToString(),
+                Name = dingTalkUser.DepartmentCode + "-" + dingTalkUser.Name,
+                Sex = dingTalkUser.Sex,
+                Department = dingTalkUser.DepartmentCode,
+                EntryDate = DateTimeOffset.FromUnixTimeMilliseconds(dingTalkUser.HiredDate).LocalDateTime,
+                Mobile = dingTalkUser.Mobile,
+                IdCard = dingTalkUser.IdCard,
+                LeaveDate = dingTalkUser?.LeaveDate,
+                LeaveReason = leaveReason,
+                LeaveReasonDescription = reasonDescription,
+                ServiceRelations = userForType?.ServiceRelations ?? string.Empty,
+                UserSocialSecurityDtos = new List<UserSocialSecurityDto>(),
+                UserHousingFundDtos = new List<UserHousingFundDto>()
+            };
+            var account = await UnitWork.Find<UserRegisterApply>(x => x.DDUserId == dingTalkUser.UserId)
+                .Select(x => x.Account)
+                .FirstOrDefaultAsync();
+            // 填充社保和公积金信息
+            if (!string.IsNullOrEmpty(account) && maps.UserIdToSocialsecurityMap.TryGetValue(account, out var socialsecurities))
+            {
+                PopulateRefundSocialSecurityLists(employee, socialsecurities);
+            }
+            else
+            {
+                // 没有社保公积金记录时，创建默认的DTO，EndPaymentTime为当月1号
+                var currentMonthStart = new DateTime(DateTime.Now.Year, DateTime.Now.Month, 1, 0, 0, 0, DateTimeKind.Local);
+                employee.UserSocialSecurityDtos = new List<UserSocialSecurityDto>
+                {
+                    new UserSocialSecurityDto { EndPaymentTime = currentMonthStart }
+                };
+                employee.UserHousingFundDtos = new List<UserHousingFundDto>
+                {
+                    new UserHousingFundDto { EndPaymentTime = currentMonthStart }
+                };
+            }
+            
+
+            if (!string.IsNullOrEmpty(account))
+            {
+                // 获取社保需要提醒的日志
+                var socialSecurityLogs = await GetEmployeeOperationLogsAsync(account, req.Type);
+                if (socialSecurityLogs.Any())
+                {
+                    employee.IsNeedRemind = socialSecurityLogs.Any(x => x.IsNeedRemind);
+                    if (employee.IsNeedRemind)
+                    {
+                        employee.Type = "信息修改";
+                    }
+                    employee.SocialsecurityOperationLogDto = ConvertToOperationLogDtos(socialSecurityLogs);
+                }
+                else
+                {
+                    employee.SocialsecurityOperationLogDto = new List<SocialsecurityOperationLogDto>();
+                }
+            }
+            else
+            {
+                employee.SocialsecurityOperationLogDto = new List<SocialsecurityOperationLogDto>();
+            }
+            
+            return employee;
+        }
+        /// <summary>
+        /// 填充退保的社保和公积金列表 (BuildRefundEmployeeDto 的子辅助)
+        /// </summary>
+        /// <param name="employee"></param>
+        /// <param name="socialsecurities"></param>
+        private void PopulateRefundSocialSecurityLists(SocialSecurityRefundEmployeeDto employee, List<UserSocialsecurity> socialsecurities)
+        {
+            // 默认停缴时间为当月1号
+            var currentMonthStart = new DateTime(DateTime.Now.Year, DateTime.Now.Month, 1, 0, 0, 0, DateTimeKind.Local);
+
+            // 社保信息
+            var socialSecurityRecords = socialsecurities
+                .Where(x => x.Type == SocialsecurityTypeEnums.Socialsecurity)
+                .ToList();
+
+            if (socialSecurityRecords.Any())
+            {
+                employee.UserSocialSecurityDtos = socialSecurityRecords
+                    .Select(x => new UserSocialSecurityDto
+                    {
+                        UpdateId = x.Id,
+                        SocialSecurityAccount = x.SocialsecurityAccount,
+                        EndPaymentTime = x.SEndPaymentTime ?? currentMonthStart,
+                        SIsEnd = x.SIsEnd,
+                        InfoUpdateTime = x.RefundInfoUpdateTime,
+                        InfoUpdateUserId = x.RefundInfoUpdateUserId,
+                        InfoUpdateUserName = !string.IsNullOrEmpty(x.RefundInfoUpdateUserId)
+                            ? _userManagerApp.GetUserOrgInfo(x.RefundInfoUpdateUserId)?.Result?.Name
+                            : null,
+                        ConfirmOpsUpdateTime = x.RefundConfirmOpsUpdateTime,
+                        ConfirmOpsUpdateUserId = x.RefundConfirmOpsUpdateUserId,
+                        ConfirmOpsUpdateUserName = !string.IsNullOrEmpty(x.RefundConfirmOpsUpdateUserId)
+                            ? _userManagerApp.GetUserOrgInfo(x.RefundConfirmOpsUpdateUserId)?.Result?.Name
+                            : null,
+                        Remark = x.Remark
+                    })
+                    .OrderByDescending(x => x.UpdateId)
+                    .ToList();
+            }
+            else
+            {
+                // 没有社保记录时，创建一个默认的DTO
+                employee.UserSocialSecurityDtos = new List<UserSocialSecurityDto>
+                {
+                    new UserSocialSecurityDto { EndPaymentTime = currentMonthStart }
+                };
+            }
+
+            // 公积金信息
+            var housingFundRecords = socialsecurities
+                .Where(x => x.Type == SocialsecurityTypeEnums.Accumulationfunds)
+                .ToList();
+
+            if (housingFundRecords.Any())
+            {
+                employee.UserHousingFundDtos = housingFundRecords
+                    .Select(x => new UserHousingFundDto
+                    {
+                        UpdateId = x.Id,
+                        SocialSecurityAccount = x.SocialsecurityAccount,
+                        EndPaymentTime = x.PEndPaymentTime ?? currentMonthStart,
+                        PIsEnd = x.PIsEnd,
+                        InfoUpdateTime = x.RefundInfoUpdateTime,
+                        InfoUpdateUserId = x.RefundInfoUpdateUserId,
+                        InfoUpdateUserName = !string.IsNullOrEmpty(x.RefundInfoUpdateUserId)
