+        /// <summary>
+        /// 验证转社保请求参数
+        /// </summary>
+        /// <param name="info">转社保信息</param>
+        /// <param name="transferType">转社保类型</param>
+        /// <returns></returns>
+        /// <exception cref="ArgumentException">参数验证失败异常</exception>
+        /// <exception cref="InvalidOperationException">业务逻辑验证失败异常</exception>
+        private async Task ValidateTransferSocialSecurityRequest(TransferSocialSecurityInfo info, TransferSocialSecurityTypeEnums transferType)
+        {
+            if (string.IsNullOrEmpty(info.DDUserId))
+            {
+                throw new ArgumentException($"用户信息中DDUserId不能为空");
+            }
+            
+            // 如果UserId为空，则根据DDUserId查找对应的UserId
+            if (string.IsNullOrEmpty(info.UserId))
+            {
+                var userRegisterInfo = await UnitWork.Find<UserRegisterApply>(r => r.DDUserId == info.DDUserId)
+                    .FirstOrDefaultAsync();
+                    
+                if (userRegisterInfo == null)
+                {
+                    throw new ArgumentException($"根据DDUserId {info.DDUserId} 未找到对应的注册信息");
+                }
+                
+                var systemUser = await UnitWork.FindSingleAsync<User>(x => x.Account == userRegisterInfo.Account);
+                if (systemUser == null)
+                {
+                    throw new ArgumentException($"根据账号 {userRegisterInfo.Account} 未找到对应的系统用户信息");
+                }
+                
+                info.UserId = systemUser.Id;
+            }
+            if (!info.BeginPaymentTime.HasValue)
+            {
+                throw new ArgumentException($"用户{info.UserId}的转入时间不能为空");
+            }
+
+            if (transferType == TransferSocialSecurityTypeEnums.TransferLaborRelation)
+            {
+                if (string.IsNullOrEmpty(info.ServiceRelations) || string.IsNullOrEmpty(info.BeforeServiceRelations))
+                {
+                    throw new ArgumentException($"转劳务关系时，用户{info.UserId}转出前后的劳务关系不能为空");
+                }
+                if (!info.EndPaymentTime.HasValue)
+                {
+                    throw new ArgumentException($"转劳务关系时，用户{info.UserId}的转出时间不能为空");
+                }
+                if (info.ServiceRelations == info.BeforeServiceRelations)
+                {
+                    throw new ArgumentException($"转劳务关系时，用户{info.UserId}转出前后劳务关系不能相同");
+                }
+            }
+
+            //离职人员不能转社保
+            var leaveUserDetail = await UnitWork.FindSingleAsync<DingTalkUserDetail>(x => x.UserId == info.DDUserId && x.HireStatus == HireStatus.Quit);
+            if (leaveUserDetail != null)
+            {
+                throw new InvalidOperationException($"用户{info.UserId}已离职，不能办理转社保业务");
+            }
+        }
+        /// <summary>
+        /// 转社保
+        /// </summary>
+        /// <param name="request">转社保请求参数</param>
+        /// <returns>处理结果消息</returns>
+        /// <exception cref="Exception">处理过程中的异常</exception>
+        public async Task TransferSocialSecurity(TransferSocialSecurityReq request)
+        {
+            // 获取当前登录用户信息
+            var loginContext = _auth.GetCurrentUser() ?? throw new CommonException(Define.LoginHasExpired, Define.INVALID_TOKEN);
+            var loginUser = loginContext.User;
+
+            if (request == null || request.TransferSocialSecurityInfos == null || request.TransferSocialSecurityInfos.Count == 0)
+            {
+                throw new ArgumentException("转社保请求参数不能为空");
+            }
+
+            try
+            {
+                foreach (var info in request.TransferSocialSecurityInfos)
+                {
+                    //验证
+                    await ValidateTransferSocialSecurityRequest(info, request.TransferType);
+
+                    // 查找用户注册信息
+                    var userRegisterInfo = await UnitWork.Find<UserRegisterApply>(r => r.DDUserId == info.DDUserId)
+                                        .Include(x => x.UserSocialsecurities)
+                                        .FirstOrDefaultAsync();
+                    
+                    if (userRegisterInfo == null)
+                    {
+                        var userDetail = await UnitWork.FindSingleAsync<DingTalkUserDetail>(x => x.UserId == info.DDUserId);
+                        throw new InvalidOperationException($"用户{userDetail?.Name ?? info.DDUserId}没有注册信息，无法办理转社保业务");
+                    }
+
+                    // 查找用户系统信息
+                    var systemUser = await UnitWork.FindSingleAsync<User>(x => x.Account == userRegisterInfo.Account);
+                    if (systemUser == null)
+                    {
+                        throw new InvalidOperationException($"未找到用户{userRegisterInfo.Account}的系统信息");
+                    }
+
+                    //社保/公积金都需要做提醒
+
+                    // 处理社保信息
+                    await TransferSocialSecurityProcess(info, userRegisterInfo, request.TransferType, loginUser.Id);
+
+                    // 处理公积金信息
+                    await TransferAccumulationfundsProcess(info, userRegisterInfo, request.TransferType, loginUser.Id);
+                    
+                    
+
+                    // 更新User表
+                    systemUser.TransferSocialSecurityFlag = EnumUtility.GetDescription(request.TransferType);
+                    if(request.TransferType == TransferSocialSecurityTypeEnums.TransferLaborRelation)
+                    {
+                        systemUser.ServiceRelations = info.ServiceRelations;
+                        systemUser.TransferBeforeServiceRelations = info.BeforeServiceRelations;
+                    }
+
+                    await UnitWork.UpdateAsync(systemUser);
+                }
+
+                // 提交所有修改
+                await UnitWork.SaveAsync();
+
+            }
+            catch (Exception ex)
+            {
+                throw new NotImplementedException($"转社保业务办理失败：{ex.Message}", ex);
+            }
+        }
