+            accountToSocialsecurityMap.TryGetValue(account, out var currentSecuritiesForUser);
+            currentSecuritiesForUser ??= new List<UserSocialsecurity>();
+
+            // 处理社保退缴
+            if (requestType == SocialsecurityTypeEnums.Socialsecurity)
+            {
+                ProcessSocialsecurityRecord(new ProcessSocialsecurityRecordParams
+                {
+                    CurrentSecurities = currentSecuritiesForUser,
+                    Type = SocialsecurityTypeEnums.Socialsecurity,
+                    UpdateId = updateRequest.UpdateId,
+                    UserId = systemUserId,
+                    Account = account,
+                    Name = userName,
+                    UpdateAction = (ss) =>
+                    {
+                        // EndPaymentTime 不再更新，保留其他字段更新逻辑
+                    },
+                    CreateCondition = () => false, // 不再创建新记录用于退缴
+                    CreateAction = (ss) =>
+                    {
+                        ss.Remark = updateRequest.Remark ?? "";
+                    },
+                    AddSocialsecurityList = changes.AddSocialsecurity,
+                    UpdateSocialsecurityList = changes.UpdateSocialsecurity,
+                    DelSocialsecurityList = changes.DelSocialsecurity,
+                    LoginUser = loginUser,
+                    OperationScene = PaymentOrRefundEnums.Refund,
+                    HasSubstantiveChange = hasSubstantiveChange
+                });
+            }
+            // 处理公积金退缴
+            else if (requestType == SocialsecurityTypeEnums.Accumulationfunds)
+            {
+                ProcessSocialsecurityRecord(new ProcessSocialsecurityRecordParams
+                {
+                    CurrentSecurities = currentSecuritiesForUser,
+                    Type = SocialsecurityTypeEnums.Accumulationfunds,
+                    UpdateId = updateRequest.UpdateId,
+                    UserId = systemUserId,
+                    Account = account,
+                    Name = userName,
+                    UpdateAction = (af) => {
+                        // EndPaymentTime 不再更新，保留其他字段更新逻辑
+                    },
+                    CreateCondition = () => false, // 不再创建新记录用于退缴
+                    CreateAction = (af) => {
+                        af.Remark = updateRequest.Remark ?? "";
+                    },
+                    AddSocialsecurityList = changes.AddSocialsecurity,
+                    UpdateSocialsecurityList = changes.UpdateSocialsecurity,
+                    DelSocialsecurityList = changes.DelSocialsecurity,
+                    LoginUser = loginUser,
+                    OperationScene = PaymentOrRefundEnums.Refund,
+                    HasSubstantiveChange = hasSubstantiveChange
+                });
+            }
