+        /// <summary>
+        /// 处理用户详情
+        /// </summary>
+        /// <param name="changes"></param>
+        /// <param name="updateRequest"></param>
+        /// <param name="requestType"></param>
+        /// <param name="accountToUserDetailMap"></param>
+        /// <param name="systemUserId"></param>
+        /// <param name="account"></param>
+        /// <param name="userName"></param>
+        private void ProcessUserDetailRefundUpdate(
+            RefundDatabaseChangeLists changes,
+            UpdateSocialReFundRequest updateRequest, // 假设这是 DTO 的类型
+            SocialsecurityTypeEnums? requestType,
+            Dictionary<string, UserDetail> accountToUserDetailMap,
+            string systemUserId,
+            string account,
+            string userName)
+        {
+            // 原始逻辑：检查 UserDetail 是否存在
+            if (accountToUserDetailMap.TryGetValue(account, out var userDetail))
+            {
+                // 存在，则检查是否需要更新
+                bool needUpdate = false;
+
+                if (requestType == SocialsecurityTypeEnums.Socialsecurity)
+                {
+                    // 社保类型：可更新离职日期和离职原因
+                    if (updateRequest.LeaveDate.HasValue)
+                    {
+                        userDetail.LeaveDate = updateRequest.LeaveDate.Value;
+                        needUpdate = true;
+                        
+                        // 同时更新User表的LeaveTime字段
+                        var user = UnitWork.Find<User>(x => x.Account == account).FirstOrDefault();
+                        if (user != null)
+                        {
+                            user.LeaveTime = updateRequest.LeaveDate.Value;
+                            changes.UpdateUser.Add(user);
+                        }
+                    }
+                    if (updateRequest.LeaveReason.HasValue)
+                    {
+                        userDetail.LeaveReason = updateRequest.LeaveReason.Value;
+                        needUpdate = true;
+                    }
+                }
+                else if (requestType == SocialsecurityTypeEnums.Accumulationfunds && updateRequest.LeaveDate.HasValue)
+                {
+                    // 公积金类型：只更新离职日期（根据原始逻辑）
+                    
+                    userDetail.LeaveDate = updateRequest.LeaveDate.Value;
+                    needUpdate = true;
+                    
+                    // 同时更新User表的LeaveTime字段
+                    var user = UnitWork.Find<User>(x => x.Account == account).FirstOrDefault();
+                    if (user != null)
+                    {
+                        user.LeaveTime = updateRequest.LeaveDate.Value;
+                        changes.UpdateUser.Add(user);
+                    }
+                }
+
+                if (needUpdate)
+                {
+                    changes.UpdateUserDetail.Add(userDetail);
+                }
+            }
+            else
+            {
+                // 不存在，则新增
+                changes.AddUserDetail.Add(new UserDetail
+                {
+                    UserId = systemUserId,
+                    Account = account,
+                    Name = userName,
+                    LeaveDate = updateRequest.LeaveDate,
+                    // 保持原始逻辑：只有社保类型才写入离职原因
+                    LeaveReason = requestType == SocialsecurityTypeEnums.Socialsecurity ? updateRequest.LeaveReason : null
+                });
+            }
+        }
