+        private async Task<(Dictionary<string, UserRegisterApply> RegisteredUserMap, string ErrorMessage)> ValidateAndGetRegisteredUsers(List<string> ddUserIds)
+        {
+            var userRegisterInfo = await UnitWork.Find<UserRegisterApply>(x => ddUserIds.Contains(x.DDUserId))
+                                                 .Select(x => new UserRegisterApply { DDUserId= x.DDUserId, Account= x.Account,Name = x.Name})
+                                                 .ToListAsync();
+
+            var missingDDUserids = ddUserIds.Except(userRegisterInfo.Select(x => x.DDUserId)).ToList();
+            if (missingDDUserids.Any())
+            {
+                var missingNames = await UnitWork.Find<DingTalkUserDetail>(x => missingDDUserids.Contains(x.UserId)).Select(x => x.Name).ToListAsync();
+                return (null, $"以下用户没有注册信息，无法修改：{string.Join(",", missingNames)}");
