+                    var missingNames = await UnitWork.Find<DingTalkUserDetail>(x => missingDDUserids.Contains(x.UserId)).Select(x => x.Name).ToListAsync();
+                    throw new NotImplementedException($"以下用户未注册，无法确认：{string.Join(", ", missingNames)}");
+                }
+                // 只处理已经注册的人员的确认请求
+                var validConfirmations = request.EmployeeConfirmations.Where(x => registeredDDUserIds.Contains(x.DDUserId)).ToList();
+                if (!validConfirmations.Any())
+                {
+                    throw new NotImplementedException("没有有效的注册用户需要处理");
+                }
+                var accountsToProcess = userRegisterInfo.Select(x => x.Account).ToList();
+
+
+                // 批量获取所有相关的社保公积金信息
+                var userSocialsecurities = await UnitWork.Find<UserSocialsecurity>(x => accountsToProcess.Contains(x.Account)).ToListAsync();
+                var accountToSecuritiesMap = userSocialsecurities.GroupBy(x => x.Account).ToDictionary(x => x.Key, x => x.ToList());
+                var updateSocialsecurityList = new List<UserSocialsecurity>();
+                var addSocialsecurityList = new List<UserSocialsecurity>();
+                var delSocialsecurityList = new List<UserSocialsecurity>(); // 谨慎使用此列表
+                                                                            // 3. 循环处理每个有效的确认请求
+                foreach (var confirmation in validConfirmations)
+                {
+                    var registerInfo = userIdToRegisterMap[confirmation.DDUserId];
+                    var account = registerInfo.Account;
+                    var systemUserIdFromRegister = confirmation.UserId; // 从注册信息中获取UserId
+                                                                        // 获取该账户下的所有现有社保公积金记录
+                    accountToSecuritiesMap.TryGetValue(account, out var currentAccountSecurities);
+                    currentAccountSecurities ??= new List<UserSocialsecurity>(); // 确保不为 null
+                                                                                 // 预先获取用于新创建记录的 UserId 和 AttachmentId (如果存在)
+                    var commonSourceForNewRecord = currentAccountSecurities
+                                                    .FirstOrDefault(x => x.Type != SocialsecurityTypeEnums.Socialsecurity && x.Type != SocialsecurityTypeEnums.Accumulationfunds);
+
+                    // 将相关数据封装到 SocialsecurityProcessingContext 对象中
+                    var context = new SocialsecurityProcessingContext
+                    {
+                        Confirmation = confirmation,
+                        RegisterInfo = registerInfo,
+                        Account = account,
+                        SystemUserId = commonSourceForNewRecord?.UserId ?? systemUserIdFromRegister, // 优先使用现有记录的UserId，否则使用注册UserId
+                        UserName = registerInfo.Name,
+                        AttachmentIdForNewRecord = commonSourceForNewRecord?.AttachmentId,
+                        CurrentAccountSecurities = currentAccountSecurities
