+                    // 处理社保记录
+                    ProcessSocialsecurityType(
+                        type: SocialsecurityTypeEnums.Socialsecurity,
+                        confirmType: SocialsecurityTypeEnums.Socialsecurity,
+                        request: request,
+                        context: context,
+                        addList: addSocialsecurityList,
+                        updateList: updateSocialsecurityList,
