+                    // 处理公积金记录
+                    ProcessSocialsecurityType(
+                        type: SocialsecurityTypeEnums.Accumulationfunds,
+                        confirmType: SocialsecurityTypeEnums.Accumulationfunds,
+                        request: request,
+                        context: context,
+                        addList: addSocialsecurityList,
+                        updateList: updateSocialsecurityList,
+                        loginUser: loginUser
+                    );
+                }
+                // 5. 批量操作数据库
+                if (delSocialsecurityList.Any())
+                {
+                    await UnitWork.BatchDeleteAsync(delSocialsecurityList.Distinct().ToArray());
+                }
+                if (addSocialsecurityList.Any())
+                {
+                    await UnitWork.BatchAddAsync<UserSocialsecurity, int>(addSocialsecurityList.ToArray());
+                }
+                if (updateSocialsecurityList.Any())
