+        /// <summary>
+        /// 根据缴纳/退缴场景写入对应的信息登记审计字段
+        /// </summary>
+        /// <param name="record"></param>
+        /// <param name="operationScene"></param>
+        /// <param name="updateTime"></param>
+        /// <param name="updateUserId"></param>
+        private static void ApplyInfoUpdateAuditFields(UserSocialsecurity record, PaymentOrRefundEnums operationScene, DateTime updateTime, string updateUserId)
+        {
+            if (operationScene == PaymentOrRefundEnums.Refund)
+            {
+                record.RefundInfoUpdateTime = updateTime;
+                record.RefundInfoUpdateUserId = updateUserId;
+                return;
+            }
+
+            record.InfoUpdateTime = updateTime;
+            record.InfoUpdateUserId = updateUserId;
+        }
+
+        /// <summary>
+        /// 根据缴纳/退缴场景写入对应的确认审计字段
+        /// </summary>
+        /// <param name="record"></param>
+        /// <param name="paymentOrRefund"></param>
+        /// <param name="updateTime"></param>
+        /// <param name="updateUserId"></param>
+        private static void ApplyConfirmAuditFields(UserSocialsecurity record, PaymentOrRefundEnums paymentOrRefund, DateTime updateTime, string updateUserId)
+        {
+            if (paymentOrRefund == PaymentOrRefundEnums.Refund)
+            {
+                record.RefundConfirmOpsUpdateTime = updateTime;
+                record.RefundConfirmOpsUpdateUserId = updateUserId;
+                return;
+            }
+
+            record.ConfirmOpsUpdateTime = updateTime;
+            record.ConfirmOpsUpdateUserId = updateUserId;
+        }
+
+        /// <summary>
+        /// 按缴纳/退缴场景判断是否已完成对应的信息登记
+        /// </summary>
+        /// <param name="record"></param>
+        /// <param name="paymentOrRefund"></param>
+        /// <returns></returns>
+        private static bool HasRegisteredForScene(UserSocialsecurity record, PaymentOrRefundEnums paymentOrRefund)
+        {
+            return paymentOrRefund == PaymentOrRefundEnums.Refund
+                ? record.RefundInfoUpdateTime.HasValue && !string.IsNullOrEmpty(record.RefundInfoUpdateUserId)
+                : record.InfoUpdateTime.HasValue && !string.IsNullOrEmpty(record.InfoUpdateUserId);
+        }
+        /// <summary>
+        /// 根据缴纳或退缴请求设置UserSocialsecurity记录的状态字段
+        /// </summary>
+        /// <param name="record"></param>
+        /// <param name="paymentOrRefund"></param>
+        private static void ApplyPaymentOrRefundStatus(UserSocialsecurity record, PaymentOrRefundEnums paymentOrRefund)
+        {
+            if (paymentOrRefund == PaymentOrRefundEnums.Payment)
+            {
+                if (record.Type == SocialsecurityTypeEnums.Socialsecurity)
+                {
+                    record.SIsPay = "Y"; // 社保缴纳
+                    record.SIsEnd = null; // 确保退缴标记被清除，或根据业务需求设置为默认值
+                }
+                else if (record.Type == SocialsecurityTypeEnums.Accumulationfunds)
+                {
+                    record.PIsPay = "Y"; // 公积金缴纳
+                    record.PIsEnd = null; // 确保退缴标记被清除
+                }
+            }
+            else if (paymentOrRefund == PaymentOrRefundEnums.Refund)
+            {
+                if (record.Type == SocialsecurityTypeEnums.Socialsecurity)
+                {
+                    record.SIsEnd = "Y"; // 社保退缴
+                    record.SIsPay = null; // 确保缴纳标记被清除
+                }
+                else if (record.Type == SocialsecurityTypeEnums.Accumulationfunds)
+                {
+                    record.PIsEnd = "Y"; // 公积金退缴
+                    record.PIsPay = null; // 确保缴纳标记被清除
+                }
+            }
+        }
